targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Complete step',
		value: {
			Environment: 'Production',
			Skipped: false,
			Step: 'Ready Environment'
		}
	};
})

